mapper.select:
SELECT COUNT(*) > 0
FROM member
WHERE is_active = 1
  AND member_id <> #{memberId}
  AND REGEXP_REPLACE(COALESCE(phone, ''), '[^0-9]', '') = #{phone}

SELECT member_id, provider, email
FROM member
WHERE name = #{name}
  AND is_active = 1
  AND REGEXP_REPLACE(COALESCE(phone, ''), '[^0-9]', '') = #{phone}
ORDER BY member_id
